// ======【结束反引号】======

// ======【结尾核心解析代码】======
function parsePlayersFromCSV(csvText) {
    const lines = csvText.trim().split(/\r?\n/);
    const players = [];

    // 跳过第 0 行的表头
    for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        // 兼容带逗号或双引号的名字
        const parts = line.split(',');
        if (parts.length >= 5) {
            const steamId = parts[0].trim();
            // 处理玩家名字中可能带引号的情况
            const name = parts[1].replace(/^["']|["']$/g, '').trim();
            const score = parseInt(parts[2], 10) || 1000;
            
            // 解析 W-L (如: 120-30)
            const wlPart = parts[4] || "0-0";
            const wlMatches = wlPart.split('-');
            const wins = parseInt(wlMatches[0], 10) || 0;
            const losses = parseInt(wlMatches[1], 10) || 0;
            const matches = wins + losses;

            // 过滤无效数字 ID
            if (steamId && /^\d+$/.test(steamId)) {
                players.push({
                    id: steamId,
                    name: name || "Unknown",
                    score: score,
                    wins: wins,
                    matches: matches
                });
            }
        }
    }
    return players;
}

module.exports = parsePlayersFromCSV(csvRawData);